    if (Get-Module -ListAvailable -Name PSReadLine) {
        Set-PSReadLineOption -Colors @{
            Default = $PSStyle.Foreground.FromRgb(23, 23, 23)
            Comment = $PSStyle.Foreground.FromRgb(82, 82, 82)
