            Variable = $PSStyle.Foreground.FromRgb(194, 65, 12)
            Member = $PSStyle.Foreground.FromRgb(29, 78, 216)
            Emphasis = $PSStyle.Foreground.FromRgb(30, 58, 138)
            Error = $PSStyle.Foreground.FromRgb(127, 29, 29)
            ContinuationPrompt = $PSStyle.Foreground.FromRgb(82, 82, 82)
            InlinePrediction = $PSStyle.Foreground.FromRgb(82, 82, 82)
            Selection = $PSStyle.Foreground.FromRgb(23, 23, 23) + $PSStyle.Background.FromRgb(189, 189, 189)
        }

        try {
            Set-PSReadLineOption -Colors @{
                ListPrediction = $PSStyle.Foreground.FromRgb(64, 64, 64)
                ListPredictionSelected = $PSStyle.Foreground.FromRgb(23, 23, 23) + $PSStyle.Background.FromRgb(189, 189, 189)
            }
        } catch { }
    }

    Set-VividLifeProperty { $PSStyle.Formatting.FormatAccent = $PSStyle.Foreground.FromRgb(127, 29, 29) }
    Set-VividLifeProperty { $PSStyle.Formatting.TableHeader = $PSStyle.Bold + $PSStyle.Foreground.FromRgb(127, 29, 29) }
    Set-VividLifeProperty { $PSStyle.Formatting.CustomTableHeaderLabel = $PSStyle.Bold + $PSStyle.Foreground.FromRgb(127, 29, 29) }
    Set-VividLifeProperty { $PSStyle.Formatting.Error = $PSStyle.Foreground.FromRgb(127, 29, 29) }
    Set-VividLifeProperty { $PSStyle.Formatting.ErrorAccent = $PSStyle.Bold + $PSStyle.Foreground.FromRgb(127, 29, 29) }
